            mismatches.check(
                H.interleavingWholeUpper(a, H.repeating(value)),
                H.Vector(
                    raw: HighwayReference.interleavingWholeUpperU64(a.raw, H.repeating(value).raw)
                ),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

